import { forbidden } from 'next/navigation';
import { verifyAdmin } from '../lib/auth';

export default async function AdminPage() {
  const { isAdmin } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-screen py-2">
      <main className="flex flex-col items-center justify-center w-full flex-1 px-20 text-center">
        <h1 className="text-6xl font-bold">
          Admin Dashboard
        </h1>

        <p className="mt-3 text-2xl">
          Welcome back, Admin!
        </p>

        <div className="flex flex-wrap items-center justify-around max-w-4xl mt-6 sm:w-full">
          <div className="p-6 mt-6 text-left border w-96 rounded-xl hover:text-blue-600 focus:text-blue-600">
            <h3 className="text-2xl font-bold">User Management &rarr;</h3>
            <p className="mt-4 text-xl">
              Manage users, roles, and permissions.
            </p>
          </div>

          <div className="p-6 mt-6 text-left border w-96 rounded-xl hover:text-blue-600 focus:text-blue-600">
            <h3 className="text-2xl font-bold">Analytics &rarr;</h3>
            <p className="mt-4 text-xl">
              View site traffic and user engagement.
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}

